import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useAppDispatch } from "../../../../app/store/hooks";
import { fetchMeals } from "../../../../app/store/slices/mealsSlice";
import {
  fetchMealsApi,
  addMealApi,
  deleteMealApi,
} from "../../api/mealsApi";

export const useMeals = (date, token) => {
  const dispatch = useAppDispatch();
  const queryClient = useQueryClient();

  // =============================
  // GET MEALS
  // =============================
  const { data: rows = [], isLoading: loading } = useQuery({
    queryKey: ["meals", date],
    queryFn: () => fetchMealsApi(token, date),
    onSuccess: (data) => {
      dispatch(fetchMeals({ date, meals: data }));
    },
    enabled: !!token,
  });

  // =============================
  // ADD MEAL
  // =============================
  const addMealMutation = useMutation({
    mutationFn: ({ mealId, amount }) => addMealApi(token, mealId, amount),
    onSuccess: () => {
      // обновляем кеш и перезапрашиваем данные
      queryClient.invalidateQueries({ queryKey: ["meals", date] });
    },
  });

  // =============================
  // DELETE MEAL
  // =============================
  const deleteMealMutation = useMutation({
    mutationFn: (mealId) => deleteMealApi(token, mealId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["meals", date] });
    },
  });

  // =============================
  // HANDLERS
  // =============================
  const handleAddMeal = (mealId, amount) => {
    addMealMutation.mutate({ mealId, amount });
  };

  const handleDeleteMeal = (mealId) => {
    deleteMealMutation.mutate(mealId);
  };

  return { rows, loading, handleAddMeal, handleDeleteMeal };
};
